const property = items[0].json;
const formatted = {
  title: `${property.title} - ${property.listingType === 'sale' ? 'For Sale' : 'For Rent'}`,
  description: property.description,
  price: property.price,
  location: property.location,
  specs: property.specs,
  images: property.images,
  features: property.features,
  listingType: property.listingType,
  agent: property.agent,
};

items.json = [{ formatted }];
return items;

const formatted = items.json[0];
const apiKey = $const('PROPERTY24_API_KEY');
const agencyId = $const('PROPERTY24_AGENCY_ID');

if (!apiKey || !agencyId) {
  throw new Error('Property24 API key or Agency ID not configured');
}

const response = await fetch('https://api.property24.co.za/listings', {
  method: 'POST',
  headers: {
    'Authorization': `Bearer ${apiKey}`,
    'Content-Type': 'application/json',
  },
  body: JSON.stringify({
    listing_type: formatted.listingType,
    property_type: 'residential',
    address: formatted.location,
    price: formatted.price,
    bedrooms: formatted.specs.bedrooms,
    bathrooms: formatted.specs.bathrooms,
    garages: formatted.specs.garages,
    description: formatted.description,
    images: formatted.images,
    features: formatted.features,
    contact: formatted.agent,
  }),
});

if (!response.ok) {
  throw new Error(`Property24 API error: ${response.status}`);
}

const data = await response.json();
items.json = [{ postUrl: `https://www.property24.co.za/p${data.listing_id}` }];
return items;

const result = {
  platform: 'property24',
  success: true,
  postUrl: items.json[0].postUrl,
};
items.json = [result];
return items;

const result = items.json[0];
const webhookUrl = $const('WEBHOOK_URL');

if (webhookUrl) {
  await fetch(webhookUrl, {
    method: 'POST',
    headers: { 'Content-Type': 'application/json' },
    body: JSON.stringify({ result, platform: 'property24' }),
  });
}

return items;
